INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (404,55,5,'Инициализация',0,'{\"variable_conversion\": [{\"variable\": \"plan_critique\", \"text\": \"\"}, {\"variable\": \"plan_iteration\", \"text\": \"0\"}, {\"variable\": \"goals_critique\", \"text\": \"\"}, {\"variable\": \"goals_iteration\", \"text\": \"0\"}, {\"variable\": \"split_critique\", \"text\": \"\"}, {\"variable\": \"split_iteration\", \"text\": \"0\"}, {\"variable\": \"plan_parse_retry\", \"text\": \"0\"}, {\"variable\": \"goals_parse_retry\", \"text\": \"0\"}, {\"variable\": \"split_parse_retry\", \"text\": \"0\"}, {\"variable\": \"task_plan_json\", \"text\": \"\"}, {\"variable\": \"task_goals_json\", \"text\": \"[]\"}, {\"variable\": \"task_subtasks_json\", \"text\": \"[]\"}, {\"variable\": \"manager_status\", \"text\": \"\"}, {\"variable\": \"manager_error\", \"text\": \"\"}], \"transitions_before\": [], \"transitions_after\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (405,55,5,'Промпт: план',3,'{\"variable_conversion\": [{\"variable\": \"manager_prompt\", \"text\": \"Теперь составь план работ по задаче, которую ты только что разобрал.\\nЗадачу, цели и свою разведку не пересказывай — ты их помнишь. Код по-прежнему не меняй.\\n\\nПланом закрой вопросы, которые сам же сформулировал на разведке, и опирайся на найденные\\nв проекте паттерны, а не на общие рассуждения.\\n\\n%if task_plan_current%=== ТЕКУЩИЙ ПЛАН ===\\n%task_plan_current%\\nЭто режим доработки: опирайся на существующий план, не переписывай с нуля.\\n\\n%endif%%if plan_critique%=== ЗАМЕЧАНИЯ ПО ПРЕДЫДУЩЕЙ ВЕРСИИ ПЛАНА ===\\n%plan_critique%\\nЗакрой все замечания, остальное в плане не трогай.\\n\\n%endif%Правила:\\n- plan_text: нумерованные шаги, 5-15 строк, конкретно — что делать и где (пути к файлам).\\n- Последний шаг — проверка результата.\\n- На подзадачи сейчас не дроби: разбиение — отдельный шаг после целей.\\n\\nФормат ответа. Нарушишь — ответ не засчитан, и я переспрошу:\\n- task_plan_json — ВСЕГДА объект с единственным ключом plan_text. Не строка, не массив,\\n  не список объектов. План в одну строку — всё равно объект.\\n- plan_text — обычный текст. Внутри него запрещены двойные кавычки и любые фрагменты\\n  JSON или кода: ключи и значения называй словами.\\n- Ответ — ровно один JSON-объект, без markdown, без ограды из обратных кавычек и без\\n  текста вокруг.\\n\\nОтветь ОДНИМ JSON-объектом:\\n{\\\"task_plan_json\\\": {\\\"plan_text\\\": \\\"детальный план текстом\\\"}}\"}], \"transitions_before\": [], \"transitions_after\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (406,55,3,'Менеджер: план',4,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"manager_prompt\", \"timeout\": \"_const_600\", \"work_dir\": \"task_shell_work_dir\"}, \"outputs_map\": {\"error\": \"manager_error\", \"status\": \"manager_status\", \"payload_json\": \"task_plan_json\"}}, \"transitions_after\": [{\"value\": \"answered\", \"step_id\": \"420\", \"operator\": \"!=\", \"variable\": \"manager_status\"}, {\"value\": \"\", \"step_id\": \"457\", \"operator\": \"empty\", \"variable\": \"task_plan_json\"}], \"transitions_before\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (407,55,3,'Счётчик итераций плана',5,'{\"tool_invoke\": {\"tool_name\": \"counter_increment\", \"inputs_map\": {\"value\": \"plan_iteration\"}, \"outputs_map\": {}}, \"transitions_before\": [], \"transitions_after\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (408,55,5,'Обновить счётчик плана',6,'{\"variable_conversion\": [{\"variable\": \"plan_iteration\", \"text\": \"%counter_increment_407_result_int%\"}], \"transitions_before\": [], \"transitions_after\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (409,55,5,'Промпт: судья плана',7,'{\"variable_conversion\": [{\"variable\": \"plan_ok\", \"text\": \"yes\"}, {\"variable\": \"plan_critique_new\", \"text\": \"\"}, {\"variable\": \"manager_prompt\", \"text\": \"Теперь проверь свой план как строгий рецензент. План ты только что выдал —\\nне пересказывай его и не переписывай. Код не меняй, только оценка.\\n\\nИтерация проверки %plan_iteration% из %max_plan_iterations%.\\n\\nФормальные требования: план покрывает описание задачи и все цели, шаги конкретные —\\nвидно что делать и где, шагов вида «разобраться» нет, есть шаг проверки результата.\\nРазбиения на подзадачи здесь не требуй — это отдельный шаг после целей.\\n\\nДальше посмотри на план с другого ракурса и ответь на новые вопросы:\\n1. Архитектура: в какие модули и файлы ложатся шаги, что меняется в схеме БД, API и фронтенде —\\n   это из плана видно или додумывается исполнителем?\\n2. Паттерны: что план переиспользует из уже существующего в проекте, а что изобретает заново?\\n   Найди похожие места в коде и назови их.\\n3. Пробелы: чего в плане нет — миграция, права доступа, обработка ошибок, обратная\\n   совместимость, документация, тесты?\\n4. Риски и порядок: какой шаг сорвётся первым и почему, что от чего зависит, верна ли\\n   последовательность шагов.\\n\\nНе выполнен хотя бы один пункт — plan_ok=no. Замечания давай новыми находками и заданиями\\nна доработку, а не пересказом плана.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown и без текста вокруг:\\n{\\\"plan_ok\\\": \\\"yes\\\", \\\"plan_score\\\": 7, \\\"plan_critique_new\\\": \\\"замечания, пустая строка если всё хорошо\\\"}\\nplan_ok — строго yes или no, plan_score — число от 1 до 10.\"}], \"transitions_before\": [], \"transitions_after\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (410,55,3,'Менеджер: судья плана',8,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"manager_prompt\", \"timeout\": \"_const_600\", \"work_dir\": \"task_shell_work_dir\"}, \"outputs_map\": {\"error\": \"manager_error\", \"status\": \"manager_status\", \"plan_ok\": \"plan_ok\", \"plan_critique_new\": \"plan_critique_new\"}}, \"transitions_after\": [{\"value\": \"answered\", \"step_id\": \"412\", \"operator\": \"!=\", \"variable\": \"manager_status\"}, {\"value\": \"yes\", \"step_id\": \"412\", \"operator\": \"==\", \"variable\": \"plan_ok\"}, {\"value\": \"%max_plan_iterations%\", \"step_id\": \"412\", \"operator\": \">=\", \"variable\": \"plan_iteration\"}, {\"value\": \"yes\", \"step_id\": \"411\", \"operator\": \"!=\", \"variable\": \"plan_ok\"}], \"transitions_before\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (411,55,5,'План на доработку',9,'{\"variable_conversion\": [{\"variable\": \"plan_critique\", \"text\": \"%plan_critique_new%\"}], \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"plan_critique\", \"operator\": \"exists\", \"value\": \"\", \"step_id\": \"405\"}]}')
