INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (412,55,5,'Промпт: цели',10,'{\"variable_conversion\": [{\"variable\": \"goals_ok\", \"text\": \"yes\"}, {\"variable\": \"goals_critique_new\", \"text\": \"\"}, {\"variable\": \"manager_prompt\", \"text\": \"Теперь по своему плану составь список целей задачи — это критерии приёмки,\\nпо ним QA будет проверять результат. Задачу и план не пересказывай, ты их помнишь.\\nКод не меняй.\\n\\n%if goals_critique%=== ЗАМЕЧАНИЯ ПО ПРЕДЫДУЩЕМУ СПИСКУ ЦЕЛЕЙ ===\\n%goals_critique%\\nПерепиши список так, чтобы все замечания были закрыты.\\n\\n%endif%Правила:\\n- Обязательно минимум 1 цель, всего 2-7, дублей нет.\\n- Цели заказчика не теряй, при необходимости уточняй формулировку.\\n- Каждая цель — проверяемый результат, а не действие.\\n- Одна строка до 100 символов, без нумерации.\\n\\nФормат ответа. Нарушишь — ответ не засчитан, и я переспрошу:\\n- task_goals_json — ВСЕГДА массив строк. Одна цель — массив из одной строки.\\n- Цели — обычный текст, без двойных кавычек и без фрагментов JSON.\\n- Ответ — ровно один JSON-объект, без markdown, без ограды из обратных кавычек и без\\n  текста вокруг.\\n\\nОтветь ОДНИМ JSON-объектом:\\n{\\\"task_goals_json\\\": [\\\"цель 1\\\", \\\"цель 2\\\", \\\"цель 3\\\"]}\"}], \"transitions_before\": [], \"transitions_after\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (413,55,3,'Менеджер: цели',11,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"manager_prompt\", \"timeout\": \"_const_600\", \"work_dir\": \"task_shell_work_dir\"}, \"outputs_map\": {\"error\": \"manager_error\", \"status\": \"manager_status\", \"payload_json\": \"task_goals_json\"}}, \"transitions_after\": [{\"value\": \"answered\", \"step_id\": \"421\", \"operator\": \"!=\", \"variable\": \"manager_status\"}, {\"value\": \"\", \"step_id\": \"460\", \"operator\": \"empty\", \"variable\": \"task_goals_json\"}], \"transitions_before\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

