INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (416,55,5,'Промпт: судья целей',14,'{\"variable_conversion\": [{\"variable\": \"goals_ok\", \"text\": \"yes\"}, {\"variable\": \"goals_critique_new\", \"text\": \"\"}, {\"variable\": \"manager_prompt\", \"text\": \"Теперь проверь свой список целей как строгий рецензент. Список ты только что\\nвыдал — не пересказывай его. Код не меняй, только оценка.\\n\\nИтерация проверки %goals_iteration% из %max_goals_iterations%.\\n\\nФормальные требования:\\n0. Список НЕ пустой — минимум 1 цель. Пустой список = критическая ошибка.\\n1. Целей 2-7, дублей нет, каждая — одна строка без нумерации.\\n2. Каждая цель — проверяемый результат, а не действие.\\n3. Цели покрывают план целиком, цели заказчика не потеряны.\\n\\nДальше посмотри с другого ракурса:\\n4. Чем именно проверяется каждая цель — командой, тестом, страницей админки, запросом к API?\\n   Если проверить нечем, цель сформулирована плохо.\\n5. Что останется непроверенным, если выполнить все цели: регрессы у соседних модулей,\\n   миграции, права доступа, поведение при ошибке.\\n\\nНе выполнен хотя бы один пункт — goals_ok=no. Замечания давай новыми находками, а не\\nпересказом списка.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown и без текста вокруг:\\n{\\\"goals_ok\\\": \\\"yes\\\", \\\"goals_score\\\": 7, \\\"goals_critique_new\\\": \\\"замечания, пустая строка если всё хорошо\\\"}\\ngoals_ok — строго yes или no, goals_score — число от 1 до 10.\"}], \"transitions_before\": [], \"transitions_after\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

