INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (422,55,5,'Промпт: разведка',1,'{\"variable_conversion\": [{\"variable\": \"manager_prompt\", \"text\": \"Ты менеджер разработки в этом проекте. Перед планированием проведи разведку задачи.\\nКод не меняй — только изучи проект.\\n\\n=== ЗАДАЧА ===\\nНазвание: %task_title%\\n\\nОписание:\\n%task_description%\\n\\n=== ЦЕЛИ ОТ ЗАКАЗЧИКА ===\\n%task_goals%\\n\\n=== ТИП ЗАДАЧИ ===\\n%if task_type%%task_type% — %task_type_title%%else%не указан%endif%\\n\\n%if project_context%=== КОНТЕКСТ ПРОЕКТА ===\\n%project_context%\\n\\n%endif%Что сделать:\\n1. Разбей описание на теги — короткие ключевые понятия: подсистемы, файлы, технологии, действия.\\n2. По тегам определи тематику: какую часть проекта задача затрагивает и что в ней меняется.\\n3. Найди в проекте похожие места и уже используемые паттерны, на которые план должен опереться.\\n   Указывай конкретные пути к файлам, а не общие слова.\\n4. Сформулируй вопросы, ответы на которые нужны, чтобы план получился конкретным.\\n   Направление вопросов бери по типу задачи:\\n   - dev — где точка входа, какие существующие паттерны переиспользовать, что менять в схеме БД,\\n     API и фронтенде, что сломается у соседних модулей;\\n   - bug — как воспроизвести, где настоящая причина, какой тест ловит регресс, где ещё живёт\\n     та же ошибка;\\n   - test — что именно проверяем, какие граничные случаи и данные нужны, где место тестов\\n     и как их гонять;\\n   - research — какие варианты сравниваем и по каким критериям, что уже пробовали в проекте,\\n     чем заканчивается исследование;\\n   - plan — из каких этапов состоит работа, что от чего зависит, где риски, чем меряем готовность;\\n   - тип не указан — бери направления по смыслу описания.\\n\\nПлан работ сейчас не пиши и решение не предлагай: это только разведка.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown и без текста вокруг:\\n{\\\"task_recon\\\": \\\"тематика, теги и найденные в проекте паттерны с путями к файлам\\\", \\\"plan_questions\\\": \\\"вопросы, по одному в строке\\\"}\"}], \"transitions_before\": [], \"transitions_after\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (423,55,3,'Менеджер: разведка',2,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"manager_prompt\", \"timeout\": \"_const_600\", \"work_dir\": \"task_shell_work_dir\"}, \"outputs_map\": {\"error\": \"manager_error\", \"status\": \"manager_status\", \"task_recon\": \"task_recon\", \"payload_json\": \"task_recon_json\", \"plan_questions\": \"plan_questions\"}}, \"transitions_after\": [{\"value\": \"answered\", \"step_id\": \"420\", \"operator\": \"!=\", \"variable\": \"manager_status\"}], \"transitions_before\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (424,55,5,'Промпт: разбиение',17,'{\"variable_conversion\": [{\"variable\": \"split_ok\", \"text\": \"yes\"}, {\"variable\": \"split_critique_new\", \"text\": \"\"}, {\"variable\": \"manager_prompt\", \"text\": \"План и цели готовы. Теперь реши сам, нужно ли разбивать эту работу на подзадачи,\\nи если нужно — на какие. Задачу, план и цели не пересказывай, ты их помнишь.\\nКод не меняй.\\n\\nСначала ответь себе на вопрос, делится ли работа вообще. Дробить стоит, когда куски\\nложатся в разные модули или слои, идут разными этапами и каждый можно сдать и\\nпроверить отдельно. Точечную правку в одном месте не дроби — у неё одна подзадача\\nна всю задачу, и это нормальный ответ, а не отписка.\\n\\n%if split_critique%=== ЗАМЕЧАНИЯ ПО ПРЕДЫДУЩЕМУ РАЗБИЕНИЮ ===\\n%split_critique%\\nЗакрой все замечания, остальное не трогай.\\n\\n%endif%Правила:\\n- Разбивать не нужно — ровно одна подзадача, покрывающая задачу целиком.\\n- Разбивать нужно — 2-7 подзадач в порядке выполнения, последняя проверяет результат.\\n- title: 3-8 слов. description: 1-3 предложения, что именно сделать и где.\\n- Вместе подзадачи покрывают весь план и все цели и не дублируют друг друга.\\n- Каждая подзадача самостоятельна: исполнитель делает её, не читая остальные.\\n\\nУ каждой подзадачи свои план и цели — общий план задачи исполнителю не выдаётся как\\nруководство к действию, он работает по плану своей подзадачи:\\n- plan — план работы именно по этой подзадаче: 2-6 шагов с новой строки, каждый\\n  начинается с «- ». Пиши конкретику этой подзадачи: какие файлы и функции трогать,\\n  в каком порядке. Общий план задачи сюда не копируй — у разных подзадач планы разные.\\n- goals — 1-4 проверяемые цели именно этой подзадачи: по ним QA примет работу.\\n  Формулируй так, чтобы ответ был «да» или «нет», без «улучшить» и «проверить».\\n  Цели задачи целиком сюда не переписывай, бери только ту их часть, которую\\n  закрывает эта подзадача.\\n- Задача неделимая и подзадача одна — план и цели у неё всё равно свои и всё равно\\n  обязательны: короткий план работы и цели, по которым её примут.\\n\\nФормат ответа. Нарушишь — ответ не засчитан, и я переспрошу:\\n- task_subtasks_json — ВСЕГДА массив объектов. Одна подзадача — массив из одного\\n  объекта, а не объект и не строка.\\n- Пустой массив недопустим: у неделимой задачи ровно одна подзадача, равная ей самой.\\n- У каждого объекта ровно четыре поля: title, description, plan, goals.\\n- goals — массив строк, не объект и не одна строка через запятую.\\n- title, description и plan — обычный текст, без двойных кавычек и без фрагментов JSON.\\n- Ответ — ровно один JSON-объект, без markdown, без ограды из обратных кавычек и без\\n  текста вокруг.\\n\\nОтветь ОДНИМ JSON-объектом:\\n{\\\"task_subtasks_json\\\": [{\\\"title\\\": \\\"краткое название\\\", \\\"description\\\": \\\"что именно сделать\\\", \\\"plan\\\": \\\"- шаг\\\\n- шаг\\\", \\\"goals\\\": [\\\"проверяемая цель\\\"]}]}\"}], \"transitions_before\": [], \"transitions_after\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (425,55,3,'Менеджер: разбиение',18,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"manager_prompt\", \"timeout\": \"_const_600\", \"work_dir\": \"task_shell_work_dir\"}, \"outputs_map\": {\"error\": \"manager_error\", \"status\": \"manager_status\", \"payload_json\": \"task_subtasks_json\"}}, \"transitions_after\": [{\"value\": \"answered\", \"step_id\": \"431\", \"operator\": \"!=\", \"variable\": \"manager_status\"}, {\"value\": \"\", \"step_id\": \"463\", \"operator\": \"empty\", \"variable\": \"task_subtasks_json\"}, {\"value\": \"[]\", \"step_id\": \"463\", \"operator\": \"==\", \"variable\": \"task_subtasks_json\"}], \"transitions_before\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

