INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (427,55,5,'Обновить счётчик разбиения',20,'{\"variable_conversion\": [{\"variable\": \"split_iteration\", \"text\": \"%counter_increment_426_result_int%\"}], \"transitions_before\": [], \"transitions_after\": []}')
