INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (428,55,5,'Промпт: судья разбиения',21,'{\"variable_conversion\": [{\"variable\": \"split_ok\", \"text\": \"yes\"}, {\"variable\": \"split_critique_new\", \"text\": \"\"}, {\"variable\": \"manager_prompt\", \"text\": \"Теперь проверь своё разбиение как строгий рецензент. Список подзадач ты только что\\nвыдал — не пересказывай его. Код не меняй, только оценка.\\n\\nИтерация проверки %split_iteration% из %max_split_iterations%.\\n\\nФормальные требования:\\n0. Список НЕ пустой — минимум 1 подзадача. Пустой список = критическая ошибка.\\n1. Подзадач 1-7, дублей нет.\\n2. Подзадачи покрывают план и цели целиком, ничего не потеряно.\\n3. Каждая — самостоятельный проверяемый кусок, шагов вида «разобраться» нет.\\n4. Подзадач больше одной — порядок выполнения верный, последняя проверяет результат.\\n5. У КАЖДОЙ подзадачи заполнены plan и goals. Пустой plan или пустой goals хотя бы\\n   у одной подзадачи = критическая ошибка.\\n\\nДальше проверь план и цели подзадач:\\n6. plan подзадачи — это план именно её работы, а не копия общего плана задачи. Два\\n   одинаковых plan у разных подзадач = ошибка.\\n7. goals подзадачи проверяемы ответом «да/нет» и относятся к её куску работы, а не\\n   к задаче целиком. Одинаковые goals у разных подзадач = ошибка.\\n8. По plan и goals подзадачи видно, что делать и когда работа принята, без чтения\\n   остальных подзадач.\\n\\nДальше проверь само решение о разбиении:\\n9. Одна подзадача — работа действительно неделимая или её просто поленились разложить?\\n10. Несколько — нет ли среди них куска, который нельзя сдать и проверить отдельно,\\n    и не слеплено ли в одну подзадачу то, что лежит в разных модулях или слоях?\\n11. Что сорвётся у исполнителя первой подзадачи, если он не видит остальных: не хватает\\n    контекста, путей к файлам, порядка зависимостей?\\n\\nНе выполнен хотя бы один пункт — split_ok=no. Замечания давай новыми находками и\\nзаданиями на доработку, а не пересказом списка.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown и без текста вокруг:\\n{\\\"split_ok\\\": \\\"yes\\\", \\\"split_score\\\": 7, \\\"split_critique_new\\\": \\\"замечания, пустая строка если всё хорошо\\\"}\\nsplit_ok — строго yes или no, split_score — число от 1 до 10.\"}], \"transitions_before\": [], \"transitions_after\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (429,55,3,'Менеджер: судья разбиения',22,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"manager_prompt\", \"timeout\": \"_const_600\", \"work_dir\": \"task_shell_work_dir\"}, \"outputs_map\": {\"error\": \"manager_error\", \"status\": \"manager_status\", \"split_ok\": \"split_ok\", \"split_critique_new\": \"split_critique_new\"}}, \"transitions_after\": [{\"value\": \"answered\", \"step_id\": \"419\", \"operator\": \"!=\", \"variable\": \"manager_status\"}, {\"value\": \"yes\", \"step_id\": \"419\", \"operator\": \"==\", \"variable\": \"split_ok\"}, {\"value\": \"%max_split_iterations%\", \"step_id\": \"419\", \"operator\": \">=\", \"variable\": \"split_iteration\"}, {\"value\": \"yes\", \"step_id\": \"430\", \"operator\": \"!=\", \"variable\": \"split_ok\"}], \"transitions_before\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

