INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (459,55,5,'Промпт: переспросить план',30,'{\"variable_conversion\": [{\"variable\": \"manager_prompt\", \"text\": \"Твой прошлый ответ не разобрался: я не смог прочитать из него task_plan_json.\\nДело в формате, а не в содержании — план заново не придумывай, повтори тот же самый.\\n\\nПереспрашиваю %plan_parse_retry% раз из %max_parse_retries%.\\n\\nЧто ломает разбор чаще всего:\\n- markdown вокруг ответа или ограда из обратных кавычек;\\n- любой текст до или после JSON-объекта;\\n- двойные кавычки или фрагменты JSON внутри plan_text;\\n- task_plan_json строкой или массивом вместо объекта.\\n\\nОтветь ОДНИМ JSON-объектом и больше ничем:\\n{\\\"task_plan_json\\\": {\\\"plan_text\\\": \\\"детальный план текстом\\\"}}\"}], \"transitions_before\": [], \"transitions_after\": [{\"value\": \"\", \"step_id\": \"406\", \"operator\": \"exists\", \"variable\": \"manager_prompt\"}]}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

