INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (462,55,5,'Промпт: переспросить цели',33,'{\"variable_conversion\": [{\"variable\": \"manager_prompt\", \"text\": \"Твой прошлый ответ не разобрался: я не смог прочитать из него task_goals_json.\\nДело в формате, а не в содержании — цели заново не придумывай, повтори те же самые.\\n\\nПереспрашиваю %goals_parse_retry% раз из %max_parse_retries%.\\n\\nЧто ломает разбор чаще всего:\\n- markdown вокруг ответа или ограда из обратных кавычек;\\n- любой текст до или после JSON-объекта;\\n- двойные кавычки или фрагменты JSON внутри целей;\\n- task_goals_json объектом или строкой вместо массива.\\n\\nОтветь ОДНИМ JSON-объектом и больше ничем:\\n{\\\"task_goals_json\\\": [\\\"цель 1\\\", \\\"цель 2\\\", \\\"цель 3\\\"]}\"}], \"transitions_before\": [], \"transitions_after\": [{\"value\": \"\", \"step_id\": \"413\", \"operator\": \"exists\", \"variable\": \"manager_prompt\"}]}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (463,55,3,'Счётчик переспросов: разбиение',34,'{\"tool_invoke\": {\"tool_name\": \"counter_increment\", \"inputs_map\": {\"value\": \"split_parse_retry\"}, \"outputs_map\": {}}, \"transitions_before\": [], \"transitions_after\": []}')
