INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (464,55,5,'Лимит переспросов: разбиение',35,'{\"variable_conversion\": [{\"variable\": \"split_parse_retry\", \"text\": \"%counter_increment_463_result_int%\"}], \"transitions_before\": [], \"transitions_after\": [{\"value\": \"%max_parse_retries%\", \"step_id\": \"431\", \"operator\": \">\", \"variable\": \"split_parse_retry\"}]}')
