INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (465,55,5,'Промпт: переспросить разбиение',36,'{\"variable_conversion\": [{\"variable\": \"manager_prompt\", \"text\": \"Твой прошлый ответ не разобрался: я не смог прочитать из него task_subtasks_json,\\nлибо список оказался пустым. Дело в формате, а не в содержании — разбиение заново не\\nпридумывай, повтори то же самое.\\n\\nПереспрашиваю %split_parse_retry% раз из %max_parse_retries%.\\n\\nПустой список — не ответ: у неделимой задачи ровно одна подзадача, равная ей самой.\\n\\nЧто ломает разбор чаще всего:\\n- markdown вокруг ответа или ограда из обратных кавычек;\\n- любой текст до или после JSON-объекта;\\n- двойные кавычки или фрагменты JSON внутри title, description и plan;\\n- task_subtasks_json объектом или строкой вместо массива объектов;\\n- goals строкой вместо массива строк.\\n\\nОтветь ОДНИМ JSON-объектом и больше ничем:\\n{\\\"task_subtasks_json\\\": [{\\\"title\\\": \\\"краткое название\\\", \\\"description\\\": \\\"что именно сделать\\\", \\\"plan\\\": \\\"- шаг\\\\n- шаг\\\", \\\"goals\\\": [\\\"проверяемая цель\\\"]}]}\"}], \"transitions_before\": [], \"transitions_after\": [{\"value\": \"\", \"step_id\": \"425\", \"operator\": \"exists\", \"variable\": \"manager_prompt\"}]}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (466,55,4,'План не разобрался',37,'{\"prompt_user\": \"json:{\\\"plan\\\": {\\\"plan_text\\\": \\\"Менеджер ответил, но план не удалось разобрать: переспросы кончились (%plan_parse_retry% из %max_parse_retries%), ответ так и не стал читаемым JSON. Последняя ошибка: %manager_error%\\\", \\\"subtasks\\\": []}, \\\"goals\\\": []}\", \"continue_workflow\": false, \"transitions_before\": [], \"transitions_after\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (444,57,5,'Инициализация',0,'{\"variable_conversion\": [{\"variable\": \"qa_critique\", \"text\": \"\"}, {\"variable\": \"qa_critique_new\", \"text\": \"\"}, {\"variable\": \"qa_iteration\", \"text\": \"0\"}, {\"variable\": \"qa_recon\", \"text\": \"\"}, {\"variable\": \"qa_checks_plan\", \"text\": \"\"}, {\"variable\": \"qa_report_json\", \"text\": \"\"}, {\"variable\": \"qa_verdict_json\", \"text\": \"\"}, {\"variable\": \"qa_ok\", \"text\": \"\"}, {\"variable\": \"qa_more\", \"text\": \"\"}, {\"variable\": \"qa_status\", \"text\": \"\"}, {\"variable\": \"qa_error\", \"text\": \"\"}], \"transitions_before\": [], \"transitions_after\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (445,57,5,'Промпт: разбор изменений',1,'{\"variable_conversion\": [{\"variable\": \"qa_prompt\", \"text\": \"Ты QA в этом проекте. Разработчик закончил одну подзадачу плана, тебе её проверять.\\nСейчас только разбор: код НЕ меняй, файлы не правь, ничего не чини, коммитов не делай.\\nНашёл дефект — это замечание разработчику, а не повод исправить самому.\\n\\n=== ЗАДАЧА ЦЕЛИКОМ ===\\nНазвание: %task_title%\\n\\nОписание:\\n%task_description%\\n\\n=== ПЛАН ЗАДАЧИ ===\\n%if task_plan_current%%task_plan_current%%else%не задан%endif%\\n\\n=== ЦЕЛИ ЗАДАЧИ ===\\n%if task_goals%%task_goals%%else%не заданы%endif%\\n\\n=== ПОДЗАДАЧА, КОТОРУЮ ПРОВЕРЯЕШЬ ===\\n#%subtask_id% %subtask_title%\\n\\n%subtask_description%\\n\\n%if subtask_plan%=== ПЛАН ПОДЗАДАЧИ ===\\n%subtask_plan%\\n\\n%endif%%if subtask_goals%=== ЦЕЛИ ПОДЗАДАЧИ (критерий приёмки) ===\\n%subtask_goals%\\n\\n%endif%%if task_dev_report%=== ОТЧЁТ РАЗРАБОТЧИКА ===\\n%task_dev_report%\\n\\nОтчёту верь только как подсказке, где смотреть: проверяешь ты код, а не отчёт.\\n\\n%else%Отчёта разработчика нет — изменения ищи сам: ветка task/%subtask_id%, git status, git diff.\\n\\n%endif%%if task_last_error%=== ЧЕМ КОНЧИЛСЯ ПРОШЛЫЙ КРУГ ===\\n%task_last_error%\\n\\n%endif%Что сделать:\\n1. Найди сами изменения: ветка task/%subtask_id%, git diff относительно master.\\n   Перечисли изменённые файлы и что в них поменялось.\\n2. Сопоставь изменения с описанием подзадачи: что закрыто, что не закрыто, что\\n   сделано сверх подзадачи.\\n3. Собери набор проверок, применимый именно здесь: существующие тесты проекта\\n   (tests/), синтаксис изменённых файлов, grep по старым ссылкам, ручная проверка\\n   через API или страницу админки.\\n4. Наметь, кого ещё могло задеть: кто зовёт изменённые функции и шаблоны.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown и без текста вокруг:\\n{\\\"qa_recon\\\": \\\"изменённые файлы и что в них поменялось\\\", \\\"qa_checks_plan\\\": \\\"проверки по пунктам: что запускаю — что считаю успехом\\\"}\"}], \"transitions_before\": [], \"transitions_after\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (446,57,3,'QA: разбор изменений',2,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"qa_prompt\", \"work_dir\": \"task_shell_work_dir\", \"timeout\": \"_const_600\"}, \"outputs_map\": {\"error\": \"qa_error\", \"status\": \"qa_status\", \"qa_recon\": \"qa_recon\", \"qa_checks_plan\": \"qa_checks_plan\"}}, \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"qa_status\", \"operator\": \"!=\", \"value\": \"answered\", \"step_id\": \"456\"}]}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (447,57,5,'Промпт: прогон проверок',3,'{\"variable_conversion\": [{\"variable\": \"qa_prompt\", \"text\": \"Прогони проверки, которые наметил. Код НЕ меняй: ты проверяешь, а не чинишь.\\nПроверка упала — это факт для отчёта, а не задание себе.\\n\\n=== ПОДЗАДАЧА ===\\n#%subtask_id% %subtask_title%\\n\\n%subtask_description%\\n\\n%if subtask_plan%=== ПЛАН ПОДЗАДАЧИ ===\\n%subtask_plan%\\n\\n%endif%%if subtask_goals%=== ЦЕЛИ ПОДЗАДАЧИ (критерий приёмки) ===\\n%subtask_goals%\\n\\n%endif%=== ЧТО ТЫ РАЗОБРАЛ ===\\n%qa_recon%\\n\\n=== НАМЕЧЕННЫЕ ПРОВЕРКИ ===\\n%qa_checks_plan%\\n\\n%if qa_critique%=== ЧТО ПРОВЕРИТЬ ДОПОЛНИТЕЛЬНО ===\\n%qa_critique%\\n\\nЭто добор к уже сделанному, а не повторный прогон всего.\\n\\n%endif%Правила прогона, они не обсуждаются:\\n- Гоняешь существующий набор тестов проекта. Новые тесты под этот прогон не\\n  пишешь и произвольный сгенерированный код не исполняешь.\\n- Рабочее дерево не меняешь: ничего не правишь, не коммитишь, не пушишь, ветки\\n  не мержишь.\\n- Чужие и общие системы не трогаешь: прод, чужие проекты, внешние сервисы.\\n- Проверяешь ветку разработчика task/%subtask_id%, а не master.\\n- Каждую проверку описываешь как «команда — результат», без пересказа кода.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown и без текста вокруг:\\n{\\\"qa_report_json\\\": {\\\"summary\\\": \\\"что проверял и чем это кончилось\\\", \\\"checks\\\": [\\\"команда — результат\\\"], \\\"failed\\\": [\\\"что не прошло, пустой список если всё прошло\\\"], \\\"coverage\\\": \\\"что осталось непроверенным и почему\\\"}}\"}], \"transitions_before\": [], \"transitions_after\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (448,57,3,'QA: прогон проверок',4,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"qa_prompt\", \"work_dir\": \"task_shell_work_dir\", \"timeout\": \"_const_1800\"}, \"outputs_map\": {\"error\": \"qa_error\", \"status\": \"qa_status\", \"payload_json\": \"qa_report_json\"}}, \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"qa_status\", \"operator\": \"!=\", \"value\": \"answered\", \"step_id\": \"456\"}, {\"variable\": \"qa_report_json\", \"operator\": \"empty\", \"value\": \"\", \"step_id\": \"456\"}]}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

