    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (450,57,5,'Обновить счётчик проверки',6,'{\"variable_conversion\": [{\"variable\": \"qa_iteration\", \"text\": \"%counter_increment_449_result_int%\"}], \"transitions_before\": [], \"transitions_after\": []}')
