INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (451,57,5,'Промпт: вердикт',7,'{\"variable_conversion\": [{\"variable\": \"qa_ok\", \"text\": \"no\"}, {\"variable\": \"qa_more\", \"text\": \"no\"}, {\"variable\": \"qa_critique_new\", \"text\": \"\"}, {\"variable\": \"qa_verdict_json\", \"text\": \"{\\\"ok\\\": false, \\\"error\\\": \\\"QA не вынес вердикт\\\"}\"}, {\"variable\": \"qa_prompt\", \"text\": \"Вынеси вердикт по подзадаче. Новых проверок сейчас не запускай, код не меняй.\\n\\nКруг проверки %qa_iteration% из %max_qa_iterations%.\\n\\n=== ОТЧЁТ О ПРОГОНЕ ===\\n%qa_report_json%\\n\\n=== ПОДЗАДАЧА ===\\n#%subtask_id% %subtask_title%\\n\\n%subtask_description%\\n\\n%if subtask_plan%=== ПЛАН ПОДЗАДАЧИ ===\\n%subtask_plan%\\n\\n%endif%%if subtask_goals%=== ЦЕЛИ ПОДЗАДАЧИ (критерий приёмки) ===\\n%subtask_goals%\\n\\n%endif%=== ЦЕЛИ ЗАДАЧИ ===\\n%if task_goals%%task_goals%%else%не заданы%endif%\\n\\nРешай по трём вопросам:\\n1. Все цели подзадачи закрыты — не наполовину и не «в основном»?\\n2. Проверки прошли, а то, что не прошло, действительно неважно?\\n3. Ничего рядом не сломано и правила проекта не нарушены?\\n\\nОтвет «нет» хотя бы на один — qa_ok=no.\\nОтдельно реши, нужен ли ещё круг проверок: qa_more=yes, если остались значимые\\nнепроверенные места, и no, если проверять больше нечего.\\n\\nВ поле error пиши замечания разработчику: что именно исправить, по пунктам, без\\nпересказа сделанного. Этот текст уйдёт ему заданием следующего круга, поэтому\\nобщие слова там бесполезны.\\n\\nОтветь ОДНИМ JSON-объектом, без markdown и без текста вокруг:\\n{\\\"qa_ok\\\": \\\"yes\\\", \\\"qa_more\\\": \\\"no\\\", \\\"qa_critique_new\\\": \\\"что проверить дополнительно, пустая строка если ничего\\\", \\\"qa_verdict_json\\\": {\\\"ok\\\": true, \\\"summary\\\": \\\"вердикт одной фразой\\\", \\\"checks\\\": [\\\"команда — результат\\\"], \\\"failed\\\": [\\\"что не прошло\\\"], \\\"error\\\": \\\"замечания разработчику, пустая строка при ok=true\\\"}}\\nqa_ok и qa_more — строго yes или no, qa_verdict_json.ok — true или false.\"}], \"transitions_before\": [], \"transitions_after\": []}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES (452,57,3,'QA: вердикт',8,'{\"tool_invoke\": {\"tool_name\": \"claude_shell_call\", \"inputs_map\": {\"role\": \"task_shell_role\", \"prompt\": \"qa_prompt\", \"work_dir\": \"task_shell_work_dir\", \"timeout\": \"_const_600\"}, \"outputs_map\": {\"error\": \"qa_error\", \"status\": \"qa_status\", \"qa_ok\": \"qa_ok\", \"qa_more\": \"qa_more\", \"qa_critique_new\": \"qa_critique_new\", \"qa_verdict_json\": \"qa_verdict_json\"}}, \"transitions_before\": [], \"transitions_after\": [{\"variable\": \"qa_status\", \"operator\": \"!=\", \"value\": \"answered\", \"step_id\": \"456\"}, {\"variable\": \"qa_ok\", \"operator\": \"==\", \"value\": \"yes\", \"step_id\": \"454\"}, {\"variable\": \"qa_iteration\", \"operator\": \">=\", \"value\": \"%max_qa_iterations%\", \"step_id\": \"455\"}, {\"variable\": \"qa_more\", \"operator\": \"!=\", \"value\": \"yes\", \"step_id\": \"455\"}, {\"variable\": \"qa_more\", \"operator\": \"==\", \"value\": \"yes\", \"step_id\": \"453\"}]}')
    ON DUPLICATE KEY UPDATE `workflow_id` = VALUES(`workflow_id`), `type_id` = VALUES(`type_id`), `title` = VALUES(`title`), `position` = VALUES(`position`), `metadata` = VALUES(`metadata`);

