INSERT INTO `agent` (`id`, `node_id`, `name`, `title`, `description`, `workflow_id`, `workflow_variable`, `prompt_system`, `greeting`, `position`, `group_name`, `dynamic`) VALUES (112,6,'task_plan_manager','Task Plan Manager','Менеджер конвейера задач: пишет план и подзадачи по описанию',55,'{}','Ты опытный менеджер разработки. Читаешь постановку задачи и превращаешь её в детальный план работ и список подзадач для команды: разработчика и QA. Планируешь конкретно — по шагам, без общих слов.\nОтвечаешь всегда одним JSON-объектом и больше ничем: без markdown, без ограды из обратных кавычек, без текста до и после. Внутри текстовых значений не используешь двойные кавычки и не вставляешь фрагменты JSON или кода — на них разбор ответа рвётся, и работу приходится переделывать.','',0,'Проекты/Task',0)
    ON DUPLICATE KEY UPDATE `node_id` = VALUES(`node_id`), `name` = VALUES(`name`), `title` = VALUES(`title`), `description` = VALUES(`description`), `workflow_id` = VALUES(`workflow_id`), `workflow_variable` = VALUES(`workflow_variable`), `prompt_system` = VALUES(`prompt_system`), `greeting` = VALUES(`greeting`), `position` = VALUES(`position`), `group_name` = VALUES(`group_name`), `dynamic` = VALUES(`dynamic`);

INSERT INTO `agent` (`id`, `node_id`, `name`, `title`, `description`, `workflow_id`, `workflow_variable`, `prompt_system`, `greeting`, `position`, `group_name`, `dynamic`) VALUES (114,6,'task_qa_tester','Task QA','QA конвейера задач: проверяет одну выполненную подзадачу плана',57,'{}','Ты придирчивый QA. Проверяешь чужую работу и ничего в ней не чинишь: найденный дефект — это замечание разработчику. Гоняешь существующий набор тестов проекта, рабочее дерево не меняешь. Всегда отвечаешь строго в JSON формате.','',0,'Проекты/Task',0)
    ON DUPLICATE KEY UPDATE `node_id` = VALUES(`node_id`), `name` = VALUES(`name`), `title` = VALUES(`title`), `description` = VALUES(`description`), `workflow_id` = VALUES(`workflow_id`), `workflow_variable` = VALUES(`workflow_variable`), `prompt_system` = VALUES(`prompt_system`), `greeting` = VALUES(`greeting`), `position` = VALUES(`position`), `group_name` = VALUES(`group_name`), `dynamic` = VALUES(`dynamic`);


-- ─── После: сверка ───────────────────────────────────────────────────────────
SELECT `w`.`id`, `w`.`name`, COUNT(`s`.`id`) AS `steps`, `a`.`id` AS `agent_id`
  FROM `agent_workflow` `w`
  LEFT JOIN `agent_workflow_step` `s` ON `s`.`workflow_id` = `w`.`id`
  LEFT JOIN `agent` `a` ON `a`.`workflow_id` = `w`.`id`
 WHERE `w`.`id` IN (55, 57)
 GROUP BY `w`.`id`;

SELECT (SELECT COUNT(*) FROM `agent_workflow_variable` WHERE `id` IN (251, 252, 256, 261, 263, 264)) AS `vars`,
       (SELECT COUNT(*) FROM `agent_workflow_variable_workflow` WHERE `workflow_id` IN (55, 57)) AS `var_links`;
